async function uptaleFetch(config, options) {
    const url = new URL(options.url, `${config.baseUrl}/`);
    // add params to url
    for (const [name, value] of Object.entries(options.params ?? {})){
        if (value !== undefined) {
            url.searchParams.set(name, String(value));
        }
    }
    const headers = new Headers({
        Authorization: `Bearer ${config.bearerToken}`
    });
    if (options.data !== undefined) {
        headers.set("Content-Type", "application/json");
    }
    let response;
    try {
        response = await fetch(url, {
            method: options.method,
            headers: headers,
            body: options.data === undefined ? undefined : JSON.stringify(options.data)
        });
    } catch (error) {
        throw new Error(`Uptale API network error for ${options.method} ${url}: ${error instanceof Error ? error.message : String(error)}`, {
            cause: error
        });
    }
    const text = await response.text();
    const responseBody = text ? JSON.parse(text) : text;
    if (!response.ok) {
        throw new Error(`Uptale API HTTP error for ${options.method} ${url}: ${response.status}. Response body: ${typeof responseBody === "string" ? responseBody : JSON.stringify(responseBody)}`);
    }
    return responseBody;
}

