async function deleteTag(input) {
    const api = createExperienceEditionApi(await createUptaleClientConfigFromEnv());
    const initialState = await api.getEditorInitialState({
        experienceId: input.experienceId
    });
    const { experienceId, sceneId, tagId } = input;
    const experience = initialState.localizedExperience;
    const scene = experience.Worlds.find((world)=>world.Id === sceneId);
    if (!scene) {
        const availableScenes = experience.Worlds.map((world)=>`${world.Name} (${world.Id})`).join(", ");
        throw new Error(`Scene ${sceneId} was not found in experience ${experienceId}. Available scenes: ${availableScenes}`);
    }
    const tag = scene.Topics.find((sceneTag)=>sceneTag.Id === tagId);
    if (!tag) {
        const availableTags = scene.Topics.map((sceneTag)=>`${sceneTag.Name} (${sceneTag.Id})`).join(", ");
        throw new Error(`Tag ${tagId} was not found in scene ${sceneId}. Available tags: ${availableTags}`);
    }
    scene.Topics = scene.Topics.filter((sceneTag)=>sceneTag.Id !== tagId);
    removeAllTagIdReferences(experience, tagId);
    // TODO: add storyboard cleanup
    const response = await api.updateExperience(experienceId, {
        experience: experience,
        force: false
    });
    const updatedScene = response.experience.Worlds.find((world)=>world.Id === sceneId);
    return {
        deletedTagId: tag.Id,
        deletedTagName: tag.Name,
        deletedTagType: tag.Type,
        sceneId: sceneId,
        totalTags: updatedScene?.Topics.length ?? scene.Topics.length
    };
}

