async function login() {
    const tokenService = createTokenService();
    await runAuthorizationCodeLogin(tokenService);
    const accessToken = await tokenService.getAccessToken();
    if (accessToken === null) {
        throw new Error("User is not logged in. Please run uptale_login first.");
    }
    return {
        status: "authenticated",
        message: "Login completed. Tokens were saved. You can now call other Uptale MCP tools.",
        authorization: `Bearer ${accessToken}`
    };
}

