function registerUpdateTagTool(server) {
    server.registerTool("update_tag", {
        description: "Update an existing tag in a scene of an Uptale experience. Fields match VRify editCurrentTag payloads. " + "Info/QCM: Content.Title, Content.Text. QCM: Answers[] partial updates are merged into the existing full Answers array. " + "Canvas/Door: Caption. Door: ToDestination. " + "Image2D/Video2D/Slides2D/Object3D: Media. Audio: Sound, not Media.",
        inputSchema: UpdateTagInputSchema
    }, async (input)=>{
        const result = await updateTag(input);
        return {
            content: [
                {
                    type: "text",
                    text: JSON.stringify(result, null, 2)
                }
            ]
        };
    });
}
async function updateTag(input) {
    const { experienceId, sceneId, tagId, tagData } = input;
    const api = createExperienceEditionApi(await createUptaleClientConfigFromEnv());
    const initialState = await api.getEditorInitialState({
        experienceId: experienceId
    });
    const experience = initialState.localizedExperience;
    const scene = experience.Worlds.find((world)=>world.Id === sceneId);
    if (!scene) {
        const availableScenes = experience.Worlds.map((world)=>`${world.Name} (${world.Id})`).join(", ");
        throw new Error(`Scene ${sceneId} was not found in experience ${experienceId}. Available scenes: ${availableScenes}`);
    }
    const tagIndex = scene.Topics.findIndex((tag)=>tag.Id === tagId);
    if (tagIndex < 0) {
        const availableTags = scene.Topics.map((tag)=>`${tag.Name} (${tag.Id})`).join(", ");
        throw new Error(`Tag ${tagId} was not found in scene ${sceneId}. Available tags: ${availableTags}`);
    }
    const tag = scene.Topics[tagIndex];
    const updatedTag = editTag(tag, toTagUpdate(tag, tagData));
    scene.Topics[tagIndex] = updatedTag;
    // TODO: update storyboard edges to match Vrify
    const response = await api.updateExperience(experienceId, {
        experience: experience,
        force: false
    });
    const updatedScene = response.experience.Worlds.find((world)=>world.Id === sceneId);
    const savedTag = updatedScene?.Topics.find((sceneTag)=>sceneTag.Id === updatedTag.Id) ?? updatedTag;
    return {
        tagId: savedTag.Id,
        tagName: savedTag.Name,
        tagType: savedTag.Type,
        sceneId: sceneId,
        tag: savedTag
    };
}

